mc(d,7,'Shared mutable state tạo race condition nên cân nhắc pattern nào?','Immutable events và event sourcing','Hardcode mọi config trong source','Manual deployment trên từng máy','Cho tất cả service ghi cùng object không version','Append-only immutable event log tránh shared mutable state và hỗ trợ event sourcing.')
mc(d,7,'Bulkhead pattern tách inference khỏi batch training nhằm mục tiêu gì?','Hạn chế failure cascade vào critical path','Bắt hai workload luôn dùng chung quota','Bỏ kiểm soát resource isolation','Thay toàn bộ circuit breaker bằng log','Critical inference cần tách non-critical batch để lỗi/cạn tài nguyên không lan; namespace/quota hỗ trợ.')
mc(d,8,'Event-driven integration giúp thêm consumer mới thế nào?','Consumer có thể nhận event mà ít ảnh hưởng producer/pipeline hiện hữu','Producer phải biết toàn bộ implementation consumer mới','Mỗi consumer buộc thay code tất cả producer','Không còn cần event contract','Kafka decouple producers/consumers; thêm consumer không cần ghép chặt lại pipeline cũ.')
mc(d,9,'Trace xuyên các lời gọi Feature Store, vector search và LLM giúp trả lời gì?','Thời gian bị tiêu ở component nào trong request tổng','Chỉ model có bao nhiêu tham số','Chỉ user thích câu trả lời không','Chỉ lịch đào tạo nhân viên','Tracing mọi call cho visibility end-to-end và giúp xác định latency breakdown/bottleneck.')
mc(d,10,'Request audit trail nên ghi model version nhằm mục tiêu gì?','Xác định chính xác model đã tạo response khi điều tra','Thay toàn bộ trace latency','Cho phép bỏ output hash','Tăng số token inference','Audit trail gồm input/output hash, latency breakdown, token cost và model version để truy vết request.')
mc(d,10,'Input hash trong audit trail hướng tới lợi ích nào?','Định danh input theo cách hạn chế lưu nội dung gốc nhạy cảm','Tự tạo thêm dữ liệu training','Thay mọi encryption key','Bảo đảm output luôn chính xác','Input hash được mô tả privacy-safe cho audit, cùng output hash và response length thay ghi toàn raw content.')
mc(d,11,'Consumer-driven contract test xác định interface mong đợi từ phía nào?','Consumer sử dụng service','Chỉ nhà cung cấp GPU','Chỉ DNS registrar','Chỉ người thiết kế màu UI','Consumer định nghĩa expected interface; CI block merge khi contract giữa service bị vi phạm.')
mc(d,11,'Testcontainers đem lại lợi ích gì cho integration test?','Chạy Postgres/Redis/Kafka thật trong Docker thay vì chỉ mock','Chỉ thay tên dependency trong report','Tự bỏ mọi test failure path','Chỉ lưu ảnh container','Real dependency containers kiểm tra integration surfaces sát thực tế; seeded data giúp biết expected output.')
mc(d,11,'Chỉ test happy path bỏ sót lớp hành vi nào?','Error handling, timeout, retry và graceful degradation','Chỉ font chữ trong console','Chỉ số lượng file README','Chỉ tên package dependency','Integration cần golden path lẫn failure path, có thể inject latency, kill pod và corrupt input để kiểm resilience.')
mc(d,12,'Muốn tìm hot function CPU trong preprocessing nên dùng gì?','cProfile hoặc py-spy','Chỉ DNS health check','Chỉ registry alias diff','Chỉ S3 lifecycle policy','cProfile/py-spy phục vụ CPU profiling; Jaeger thấy bottleneck service ở cấp request.')
mc(d,12,'Một service tăng memory theo thời gian cần công cụ nào để xem allocation?','tracemalloc','EXPLAIN ANALYZE cho mọi Python allocation','tc như công cụ model registry','Kafka partition key','tracemalloc theo dõi memory allocation, hỗ trợ tìm memory leak trong long-running service.')
mc(d,12,'Database query chậm và nghi thiếu index nên kiểm tra bằng gì?','EXPLAIN ANALYZE','Chỉ py-spy flamegraph UI','Chỉ tăng token budget','Chỉ đổi prompt alias','EXPLAIN ANALYZE nhắm database queries/slow query/missing index; chọn profiler theo tầng bottleneck.')
mc(d,13,'Vì sao cần theo dõi P50, P95, P99 từng service thay chỉ một latency trung bình?','Nhìn được cả trường hợp phổ biến và phần đuôi chậm trong chuỗi request','Bảo đảm mọi request có cùng latency','Loại bỏ nhu cầu end-to-end tracing','Tự giảm số network call','Profiling checklist yêu cầu các percentile theo service, cùng CPU/memory/GPU/network để nhìn hiệu năng thực.')
mc(d,14,'Production readiness checklist nên được thực thi thế nào để nhất quán mỗi deploy?','Tự động hóa kiểm tra trong CI','Chỉ dựa trí nhớ người release','Chỉ kiểm một lần lúc bắt đầu dự án','Chỉ đánh dấu sau khi user báo sự cố','Automated checklist mỗi deploy giảm phụ thuộc human memory và giữ các trụ reliability/observability/security/performance/ops.')
mc(d,15,'Graceful shutdown xử lý điều gì khi service được dừng?','Các request đang xử lý in-flight','Chỉ file log đã archive','Chỉ tên model trên UI','Chỉ số lượng cron job','Readiness checklist gồm graceful shutdown handles in-flight bên cạnh health checks, retry và circuit breaker.')
mc(d,20,'Để platform dùng được bởi team khác, điều gì cần được coi trọng ngoài code nội bộ?','API contracts, documentation và SLA','Chỉ code style của một người','Chỉ chạy thành công trên máy tác giả','Chỉ tên framework hiện đại','Platform có giá trị khi team khác dùng được; contracts/docs/SLA là giao diện cộng tác cần thiết.')
